// C implementation of vstodo cmdShow header
//\n// NOTE: This is a skeleton implementation for migration purposes.\n// It follows the Go cmd_show.go command interface.\n//\n// This file cannot be compiled/verified locally per AGENTS.md constraints\n// (no C compiler available). It is provided as the intended C replacement\n// for cmd_show.go.\n\n#ifndef VSTODO_C_CMD_SHOW_H\n#define VSTODO_C_CMD_SHOW_H\n\n// Display the content of a repository object.\n// Equivalent to Go cmdShow function.\n// app — vstodo application context pointer\n// args — object identifiers (blob, tree, commit, tag IDs)\n// arg_count — number of arguments\n//\n// Returns 0 on success, negative error code on failure.\nint cmd_show(void *app, const char **args, int arg_count);\n\n#endif // VSTODO_C_CMD_SHOW_H